const TOKEN_URL = "https://github.com/login/oauth/access_token";

export async function exchangeCode(code: string, verifier: string) {
  const res = await fetch(TOKEN_URL, {
    method: "POST",
    headers: { Accept: "application/json", "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      client_id: process.env.GITHUB_CLIENT_ID!,
      client_secret: process.env.GITHUB_CLIENT_SECRET!,
      code,
      redirect_uri: process.env.GITHUB_REDIRECT_URI!,
      code_verifier: verifier,
    }),
  });
  if (res.status === 404) throw new Error("GitHub token endpoint 404: check client_id/secret for this environment");
  const json = await res.json();
  if (json.error) throw new Error(`${json.error}: ${json.error_description ?? ""}`);
  return json as { access_token: string; refresh_token?: string; expires_in?: number; refresh_token_expires_in?: number; scope: string };
}

export async function refresh(refreshToken: string) {
  const res = await fetch(TOKEN_URL, {
    method: "POST",
    headers: { Accept: "application/json", "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      client_id: process.env.GITHUB_CLIENT_ID!,
      client_secret: process.env.GITHUB_CLIENT_SECRET!,
      grant_type: "refresh_token",
      refresh_token: refreshToken,
    }),
  });
  const json = await res.json();
  if (json.error === "bad_refresh_token") throw new Error("REAUTH_REQUIRED");
  if (json.error) throw new Error(json.error);
  return json; // persist BOTH new access_token and new refresh_token
}
